<template>
  <section class="destiny-card-board" aria-label="命格翻牌">
    <header class="board-head"><div><p class="eyebrow">命格牌阵</p><h3>{{ activeDimension?.label ?? '等待取证' }}</h3></div><aside ref="vaultRef" class="vault" aria-label="命格藏牌匣"><button class="vault-toggle" type="button" :aria-expanded="vaultOpen" :disabled="!archivedDimensions.length" @click="vaultOpen = !vaultOpen"><span>命格藏牌匣 · {{ archivedDimensions.length }}</span><span v-if="archivedDimensions.length" class="vault-stack" aria-hidden="true"><img v-for="(dimension, index) in archivedDimensions" :key="dimension.key" :src="cardBack" alt="" :style="{ '--stack-index': index }" /></span><span v-else class="vault-empty" aria-hidden="true" /></button><Transition name="vault-drawer"><section v-if="vaultOpen" class="vault-drawer" aria-label="已收纳的命格卡"><header><div><small>已收纳</small><strong>{{ archivedDimensions.length }} 张命格卡</strong></div><button type="button" aria-label="收起藏牌匣" title="收起" @click="vaultOpen = false">×</button></header><div class="vault-fan"><button v-for="dimension in archivedDimensions" :key="`archive-${dimension.key}`" type="button" @click="restoreDimension(dimension.key)"><img :src="frontImageFor(dimension.key)" alt="" /><span><strong>{{ dimension.label }}</strong><small>{{ dimension.display_value }}</small><b>{{ confidenceText(dimension) }}</b></span></button></div></section></Transition></aside></header>
    <p class="board-hint">{{ activeDimension ? `${activeDimension.label}已达到显影条件；牌面比例只表示已观察到的组成。` : '对话会逐步收集七维线索；达到置信度后自动翻牌。' }}<span v-if="activeDimension" :class="['confidence-state', confidenceBand(activeDimension)]">{{ confidenceLabel(activeDimension) }} {{ confidenceText(activeDimension) }}</span></p>
    <div class="card-grid" :class="{ 'is-open': Boolean(activeDimension) }"><article v-for="slot in slots" :key="slot.index" :class="['image-card', { 'is-empty': !slot.item, 'is-selected': selectedSlot?.index === slot.index }]" :style="{ '--card-delay': `${slot.index * 130}ms` }" :aria-label="slot.item && activeDimension ? `${activeDimension.label}：${slot.name}，${percent(slot.ratio)}%` : '空白卡位'" :tabindex="slot.item ? 0 : -1" @click="selectSlot(slot)" @keydown.enter.prevent="selectSlot(slot)" @keydown.space.prevent="selectSlot(slot)"><div class="card-inner"><div class="card-face card-back"><img :src="cardBack" alt="" /></div><div class="card-face card-front"><img :src="activeDimension ? frontImageFor(activeDimension.key) : learningGoalCard" alt="" /><template v-if="slot.item && activeDimension"><div class="front-copy"><span>{{ activeDimension.label }}</span><i aria-hidden="true" /><strong>{{ slot.name }}</strong><small>{{ slot.description }}</small><b>{{ percent(slot.ratio) }}<em>%</em></b></div><div class="card-meaning" role="tooltip"><strong>{{ slot.name }}</strong><span>{{ slot.meaning }}</span><small>点击查看判断依据</small></div></template><span v-else class="empty-copy">未成形</span></div></div></article></div>
    <Transition name="reading-slip"><aside v-if="selectedSlot?.item && activeDimension" class="reading-slip" aria-live="polite"><header><div><small>解牌笺 · {{ activeDimension.label }}</small><strong>{{ selectedSlot.name }}</strong></div><button type="button" aria-label="收起解牌笺" title="收起" @click="selectedSlot = null">×</button></header><p>{{ selectedSlot.meaning }}</p><dl><div><dt>为何成牌</dt><dd>{{ activeDimension.explanation }}</dd></div><div><dt>当前确认</dt><dd><span :class="['confidence-state', confidenceBand(activeDimension)]">{{ confidenceLabel(activeDimension) }} {{ confidenceText(activeDimension) }}</span>；已覆盖 {{ coverageText(activeDimension) }}</dd></div><div v-if="activeDimension.unknown_reasons?.length"><dt>仍待了解</dt><dd>{{ activeDimension.unknown_reasons.join('；') }}</dd></div><div><dt>证据所出</dt><dd>{{ selectedSlot.sources }}</dd></div></dl><blockquote v-for="quote in selectedSlot.quotes" :key="quote">“{{ quote }}”</blockquote></aside></Transition>
  </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import type { DimensionKey, IdentityCardItem, IdentityCardsDimensionView } from '../../types/profile'
import cardBack from '../../assets/profile-cards/destiny-card-back-transparent.png'
import learningGoalCard from '../../assets/profile-cards/learning-goal-card.png'
import paceCard from '../../assets/profile-cards/pace-card.png'
import knowledgeBaseCard from '../../assets/profile-cards/knowledge-base-card.png'
import learningStyleCard from '../../assets/profile-cards/learning-style-card.png'
import weakPointsCard from '../../assets/profile-cards/weak-points-card.png'
import motivationCard from '../../assets/profile-cards/motivation-card.png'
import resourcePreferenceCard from '../../assets/profile-cards/resource-preference-card.png'
type RevealedDimension = IdentityCardsDimensionView & { revealAnimation?: boolean }
const props = defineProps<{ dimensions: RevealedDimension[] }>()
const activeDimensionKey = ref<DimensionKey | null>(null); const archivedKeys = ref<DimensionKey[]>([]); const vaultOpen = ref(false); const vaultRef = ref<HTMLElement | null>(null); let archiveTimer: ReturnType<typeof window.setTimeout> | null = null
type CardSlot = { index: number; item?: IdentityCardItem; ratio: number; name: string; description: string; meaning: string; quotes: string[]; sources: string }
const selectedSlot = ref<CardSlot | null>(null)
const fronts: Record<DimensionKey, string> = { learning_goal: learningGoalCard, pace: paceCard, knowledge_base: knowledgeBaseCard, learning_style: learningStyleCard, weak_points: weakPointsCard, motivation: motivationCard, resource_preference: resourcePreferenceCard }
const activeDimension = computed(() => props.dimensions.find((item) => item.key === activeDimensionKey.value) ?? null)
const archivedDimensions = computed(() => archivedKeys.value.map((key) => props.dimensions.find((item) => item.key === key)).filter((item): item is RevealedDimension => Boolean(item)))
const frontImageFor = (key: DimensionKey) => fronts[key] ?? learningGoalCard
const percent = (ratio?: number) => Math.round(Math.max(0, Math.min(1, ratio ?? 0)) * 100)
const confidenceText = (dimension: IdentityCardsDimensionView) => `${percent(dimension.confidence)}%`
const confidenceBand = (dimension: IdentityCardsDimensionView) => dimension.confidence < .5 ? 'is-low' : dimension.confidence < .7 ? 'is-mid' : 'is-high'
const confidenceLabel = (dimension: IdentityCardsDimensionView) => dimension.confidence < .5 ? '待确认' : dimension.confidence < .7 ? '初步确认' : '较为稳定'
const coverageText = (dimension: IdentityCardsDimensionView) => `${percent(dimension.coverage)}%`
const itemName = (item: IdentityCardItem) => item.display_name || item.level_name || item.label || item.canonical_label || '未命名线索'
const itemDescription = (item: IdentityCardItem) => item.canonical_label && item.canonical_label !== itemName(item) ? item.canonical_label : '由本轮线索显影'
const cardsFor = (dimension: IdentityCardsDimensionView | null) => dimension ? (dimension.items ?? []).filter((item) => !item.placeholder).slice(0, 4) : []
const slots = computed<CardSlot[]>(() => { const items = cardsFor(activeDimension.value); return Array.from({ length: 4 }, (_, index) => { const item = items[index]; return { index, item, ratio: item ? (item.ratio ?? 1 / items.length) : 0, name: item ? itemName(item) : '', description: item ? itemDescription(item) : '', meaning: item?.meaning || '由当前对话线索提炼，仍会随新证据调整', quotes: (item?.quotes ?? []).map(String).slice(0, 3), sources: (item?.evidence_refs ?? []).join('、') || '本轮问诊式对话' } }) })
const selectSlot = (slot: CardSlot) => { if (slot.item) selectedSlot.value = selectedSlot.value?.index === slot.index ? null : slot }
const archiveActive = () => { const key = activeDimensionKey.value; if (key && !archivedKeys.value.includes(key)) archivedKeys.value = [...archivedKeys.value, key]; activeDimensionKey.value = null; selectedSlot.value = null; archiveTimer = null }
const restoreDimension = (key: DimensionKey) => { activeDimensionKey.value = key; selectedSlot.value = null; vaultOpen.value = false }
const reveal = (dimension: RevealedDimension) => { if (archiveTimer) window.clearTimeout(archiveTimer); activeDimensionKey.value = dimension.key; selectedSlot.value = null; archiveTimer = window.setTimeout(archiveActive, 8000) }
const closeOnOutside = (event: PointerEvent) => { if (vaultOpen.value && !vaultRef.value?.contains(event.target as Node)) vaultOpen.value = false }
const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape') vaultOpen.value = false }
watch(() => props.dimensions, (dimensions) => {
  const newlyRevealed = dimensions.find((dimension) => dimension.revealAnimation && dimension.confidence >= 0.5)
  if (newlyRevealed) reveal(newlyRevealed)
  const revealedKeys = dimensions.filter((dimension) => dimension.revealed && dimension.key !== activeDimensionKey.value).map((dimension) => dimension.key)
  archivedKeys.value = Array.from(new Set([...archivedKeys.value, ...revealedKeys]))
}, { deep: true, immediate: true })
onMounted(() => { document.addEventListener('pointerdown', closeOnOutside); document.addEventListener('keydown', closeOnEscape) })
onBeforeUnmount(() => { if (archiveTimer) window.clearTimeout(archiveTimer); document.removeEventListener('pointerdown', closeOnOutside); document.removeEventListener('keydown', closeOnEscape) })
</script>
<style scoped lang="scss">
@use '../../styles/tokens.scss' as *;
