2px;padding:3px 9px;border:1px solid var(--qh-color-paper-line);border-radius:var(--qh-radius-pill);color:var(--qh-card-metric);background:var(--qh-card-metric-bg);font-family:var(--qh-font-display);font-size:clamp(15px,1.35vw,21px);font-weight:900}.front-copy em{font-size:.58em;font-style:normal}.empty-copy{position:absolute;top:54%;left:0;right:0;color:#a78e66;font-size:11px;text-align:center}.image-card.is-empty .card-front{filter:saturate(.55) opacity(.76)}
.vault{position:relative;display:grid;justify-items:center;width:118px}.vault-toggle{display:grid;justify-items:center;gap:5px;padding:0;border:0;color:var(--qh-color-gold);background:none;cursor:pointer;font:inherit;font-family:var(--qh-font-display);font-size:12px;font-weight:900}.vault-toggle:disabled{cursor:default}.vault-toggle:focus-visible{outline:2px solid var(--qh-color-jade);outline-offset:4px}.vault-empty,.vault-stack{width:54px;height:81px}.vault-empty{border:1px dashed color-mix(in srgb,var(--qh-color-gold) 58%,transparent);border-radius:3px}.vault-stack{position:relative}.vault-stack img{position:absolute;bottom:0;left:calc(var(--stack-index) * 4px);width:54px;height:81px;object-fit:cover;border:1px solid color-mix(in srgb,var(--qh-color-gold) 55%,transparent);transform:rotate(calc(var(--stack-index) * 2deg - 3deg));transform-origin:bottom center}.vault-drawer{position:absolute;z-index:20;top:0;right:0;width:min(620px,calc(100vw - 32px));padding:14px;border:1px solid var(--qh-color-jade-line);border-radius:var(--qh-radius-stage);background:var(--qh-vault-fill);box-shadow:var(--qh-shadow-deep);backdrop-filter:blur(18px)}.vault-drawer header{display:flex;align-items:center;justify-content:space-between}.vault-drawer header div{display:grid;gap:2px}.vault-drawer header small{color:var(--qh-color-jade);font-size:11px}.vault-drawer header strong{color:var(--qh-text);font-size:14px}.vault-drawer header button{display:grid;width:32px;height:32px;padding:0;place-items:center;border:0;color:var(--qh-text-muted);background:none;cursor:pointer;font-size:24px}.vault-fan{display:flex;margin-top:12px;padding:6px 6px 10px;overflow-x:auto}.vault-fan>button{position:relative;display:grid;flex:0 0 116px;height:168px;padding:0;border:0;background:none;cursor:pointer;transition:transform var(--qh-duration-md) ease}.vault-fan>button+button{margin-left:-35px}.vault-fan>button:hover,.vault-fan>button:focus-visible{z-index:2;transform:translateY(-6px)}.vault-fan img{width:100%;height:100%;object-fit:contain}.vault-fan span{position:absolute;inset:auto 12px 17px;display:grid;gap:2px;padding:6px;background:var(--qh-card-caption-fill);color:var(--qh-color-paper-ink);text-align:center}.vault-fan span strong{font-size:12px}.vault-fan span small{overflow:hidden;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.vault-fan span b{color:var(--qh-card-metric);font-size:11px}.vault-drawer-enter-active,.vault-drawer-leave-active{transition:opacity var(--qh-duration-md) ease,transform var(--qh-duration-md) ease}.vault-drawer-enter-from,.vault-drawer-leave-to{opacity:0;transform:translateX(18px)}
.destiny-card-board { position: relative; }
.front-copy { top: 40%; }
.front-copy > span { display: block; transform: translateY(3px); }
.front-copy i { margin-block: 3px; }
.front-copy strong { line-height: 1.08; }
.front-copy small { min-height: 1.5em; margin-top: 2px; line-height: 1.3; }
.front-copy b { margin-top: -2px; padding: 0; border: 0; border-radius: 0; background: transparent; box-shadow: none; text-shadow: none; }
.image-card:not(.is-empty){cursor:pointer;outline:none}.image-card:not(.is-empty):focus-visible{outline:2px solid var(--qh-color-jade);outline-offset:3px}.card-meaning{position:absolute;z-index:4;right:7%;bottom:7%;left:7%;display:grid;gap:3px;padding:8px 9px;border:1px solid var(--qh-color-paper-line);background:var(--qh-card-caption-fill);color:var(--qh-color-paper-ink);opacity:0;transform:translateY(5px);transition:opacity var(--qh-duration-fast) ease,transform var(--qh-duration-fast) ease;pointer-events:none;text-align:left;box-shadow:var(--qh-shadow-soft)}.card-meaning strong{font-size:12px}.card-meaning span{font-size:10px;line-height:1.45}.card-meaning small{color:var(--qh-card-metric);font-size:9px}.image-card:hover .card-meaning,.image-card:focus-visible .card-meaning{opacity:1;transform:translateY(0)}.reading-slip{position:absolute;z-index:18;right:14px;bottom:14px;width:min(360px,calc(100% - 28px));padding:16px;border:1px solid var(--qh-button-gold-line);border-radius:var(--qh-radius-card);background:var(--qh-vault-fill);box-shadow:var(--qh-shadow-deep);backdrop-filter:blur(16px)}.reading-slip header{display:flex;align-items:start;justify-content:space-between;gap:12px}.reading-slip header div{display:grid;gap:3px}.reading-slip header small{color:var(--qh-color-gold);font-size:11px}.reading-slip header strong{color:var(--qh-text);font-family:var(--qh-font-display);font-size:20px}.reading-slip button{display:grid;width:30px;height:30px;padding:0;place-items:center;border:0;background:none;color:var(--qh-text-muted);cursor:pointer;font-size:22px}.reading-slip>p{margin:10px 0;color:var(--qh-text);font-size:13px;line-height:1.65}.reading-slip dl{display:grid;gap:8px;margin:0}.reading-slip dl div{display:grid;grid-template-columns:64px 1fr;gap:8px}.reading-slip dt{color:var(--qh-color-jade);font-size:11px;font-weight:900}.reading-slip dd{margin:0;color:var(--qh-text-muted);font-size:11px;line-height:1.55}.reading-slip blockquote{margin:8px 0 0;padding:7px 9px;border-left:2px solid var(--qh-color-gold);color:var(--qh-text-muted);font-size:11px;line-height:1.55}.reading-slip-enter-active,.reading-slip-leave-active{transition:opacity var(--qh-duration-fast) ease,transform var(--qh-duration-fast) ease}.reading-slip-enter-from,.reading-slip-leave-to{opacity:0;transform:translateY(8px)}
.vault-stack img { bottom: calc(var(--stack-index) * 2px); left: calc(var(--stack-index) * 3px); transform: none; }
@media(max-width:1080px){.destiny-card-board{min-height:560px}.front-copy{top:41%}}@media(max-width:680px){.vault-drawer{position:fixed;top:12px;right:12px;left:12px;width:auto}.vault-fan>button{flex-basis:104px;height:150px}.card-meaning{display:none}}@media(prefers-reduced-motion:reduce){.card-inner,.vault-fan>button,.card-meaning,.reading-slip{transition:none}}
</style>
